"""Minimal path router for the internal status service."""


class Router:
    """Maps URL paths to handlers.

       Routes are registered with `add`, and `resolve` returns (handler, params)
       for a path or (None, {}) when nothing matches.
    """

    def __init__(self):
        self._routes = []

    def add(self, path, handler):
        self._routes.append((path, handler))

    def resolve(self, path):
        # Parse the requested path into segments
        path_segs = _split_path(path)

        static_matches = []
        dynamic_matches = []

        for route, handler in self._routes:
            if route == path:
                return handler, {}

            route_segs = _split_path(route)

            # Segment counts must match exactly
            if len(path_segs) != len(route_segs):
                continue

            params, matched = _match_segments(path_segs, route_segs)
            if not matched:
                continue

            # Check if this is a static route (no parameters at all)
            has_param = any(_is_parameter(seg) for seg in route_segs)

            if has_param:
                dynamic_matches.append((handler, params))
            else:
                # Static route that matches - should win over dynamic
                static_matches.append((handler, {}))

        # A static route must win over a dynamic route that also matches
        if static_matches:
            # Return the first statically matching route (respecting order)
            return static_matches[0]

        if dynamic_matches:
            return dynamic_matches[0]

        return None, {}


def _split_path(path):
    """Split a path into segments."""
    if not path.startswith('/'):
        return []
    raw = path.split('/')
    # The first element is empty due to leading /
    segs = [s for s in raw[1:] if s != '']
    return segs


def _is_parameter(segment):
    """Check if a segment is a parameter like <name>."""
    return segment.startswith('<') and segment.endswith('>')


def _match_segments(path_segs, route_segs):
    """Match path segments against route segments. Returns (params, matched)."""
    params = {}

    for path_seg, route_seg in zip(path_segs, route_segs):
        if _is_parameter(route_seg):
            # This is a parameter segment - the value must be non-empty
            if path_seg == '':
                return {}, False
            param_name = route_seg[1:-1]  # Remove <> brackets
            params[param_name] = path_seg
        else:
            # Static segment - must match exactly
            if path_seg != route_seg:
                return {}, False

    return params, True

