"""A tiny TTL cache used by the metrics collector."""

from collections import OrderedDict


class TTLCache:
    """Mapping with per-entry expiry.

    `clock` is a zero-argument callable returning a monotonic float, injected so
    tests can control time.
    """

    def __init__(self, ttl, clock, max_size=None):
        self.ttl = ttl
        self.clock = clock
        self.max_size = max_size
        # OrderedDict maintains insertion order; we'll move items to end on access (get or update)
        self._data = OrderedDict()

    def set(self, key, value):
        if key in self._data:
            del self._data[key]
        elif self.max_size is not None and self.max_size > 0:
            # For new entry, check capacity (evict expired first) before adding
            self._cleanup_expired()
            while len(self._data) >= self.max_size:
                # Evict least recently used (first item in OrderedDict)
                self._pop_lru()
        elif self.max_size is not None and self.max_size == 0:
            # max_size=0 means retain nothing - don't add at all
            return
        self._data[key] = (value, self.clock())

    def _cleanup_expired(self):
        """Remove expired entries. Called before checking capacity."""
        current = self.clock()
        to_remove = [k for k, (_, t) in list(self._data.items()) if current - t >= self.ttl]
        for k in to_remove:
            del self._data[k]

    def _pop_lru(self):
        """Remove the least recently used entry (first item)."""
        try:
            self._data.popitem(last=False)
        except KeyError:
            pass

    def get(self, key, default=None):
        entry = self._data.get(key)
        if entry is None:
            return default
        value, stamp = entry
        if self.clock() - stamp >= self.ttl:
            del self._data[key]
            return default
        # Count as a use - update recency by moving to end of OrderedDict
        self._data.move_to_end(key)
        return value

    def __len__(self):
        return len(self._data)

