class Router:
     """Maps URL paths to handlers.

    Routes are registered with `add`, and `resolve` returns (handler, params)
    for a path or (None, {}) when nothing matches.
     """

     def __init__(self):
          self._routes = []

     def add(self, path, handler):
          self._routes.append((path, handler))

     def _match_segment(self, route_seg, path_seg, params):
         """Match a single segment. Return True if match, populating params."""
         # Empty segment cannot satisfy anything
         if path_seg == '':
              return False

         if route_seg.startswith('<') and route_seg.endswith('>'):
              param_name = route_seg[1:-1]
              params[param_name] = path_seg
              return True
         else:
              return route_seg == path_seg

     def resolve(self, path):
          """Resolve a path to handler and captured parameters.

        Returns (handler, params) where params is a dict of captured values.

        Rules:
         - Segment counts must match exactly
         - An empty segment must not satisfy a parameter
         - Static routes win over dynamic routes regardless of registration order
         - Among same-type routes, first registered wins
         """
         # Parse the request path into raw segments for counting
         path_raw = [s for s in path.split('/') if s != '']

         # Collect all matching routes along with their type and params
         static_candidates = []        # indices of matching static routes
         dynamic_candidates = []       # (index, handler, params) for matching param routes

         for idx, (route, handler) in enumerate(self._routes):
              route_raw = [s for s in route.split('/') if s != '']

              # Segment counts must match exactly
              if len(route_raw) != len(path_raw):
                   continue

              # Try to match each segment and collect params
              params = {}
              matches = True
              for r_seg, p_seg in zip(route_raw, path_raw):
                   if not self._match_segment(r_seg, p_seg, params):
                        matches = False
                        break

              if not matches:
                   continue

              # Record this match - static routes have no '<...>' syntax
              is_static = '<' not in route or '>' not in route   # no param syntax = static
              if is_static:
                   static_candidates.append(idx)
              else:
                   dynamic_candidates.append((idx, handler, params))

         # Static routes win over dynamic (regardless of registration order)
         if static_candidates:
             first_static_idx = min(static_candidates)
             return self._routes[first_static_idx][1], {}

         # Return first dynamic match by registration order
         if dynamic_candidates:
              _, handler, params = min(dynamic_candidates, key=lambda x: x[0])
              return handler, params

         return None, {}

