"""A tiny TTL cache used by the metrics collector."""


class TTLCache:
    """Mapping with per-entry expiry.

   `clock` is a zero-argument callable returning a monotonic float, injected so
   tests can control time.

   `max_size` (optional): maximum number of entries; when set, cache evicts 
   least recently used entry to make room. If max_size=0, the cache retains nothing.
    """

    def __init__(self, ttl, clock, max_size=None):
        self.ttl = ttl
        self.clock = clock
        self.max_size = max_size
        self._data = {}

    def set(self, key, value):
         # If overwriting an existing key, update in place (no size change)
        if key in self._data:
            self._data[key] = (value, self.clock())
            return

         # Add entry first, then evict from front while over capacity
        self._data[key] = (value, self.clock())
        if self.max_size is not None:
            while len(self._data) > self.max_size and self._data:
                lru_key = next(iter(self._data))
                del self._data[lru_key]

    def get(self, key, default=None):
        entry = self._data.get(key)
        if entry is None:
            return default
        value, stamp = entry
        if self.clock() - stamp >= self.ttl:
            del self._data[key]
            return default
         # Moving to end counts as a use (LRU tracking)
        self._data.pop(key)
        self._data[key] = (value, stamp)
        return value

    def __len__(self):
        return len(self._data)

