import re


class Router:
    """Maps URL paths to handlers.

    Routes are registered with `add`, and `resolve` returns (handler, params)
    for a path or (None, {}) when nothing matches.
    """

    def __init__(self):
        self._static_routes = []  # For static routes
        self._dynamic_routes = []  # For routes with parameters

    def _segments(self, path):
        """Split path into non-empty segments."""
        return [s for s in path.split("/") if s]

    def _is_static_segment(self, seg):
        """Check if a segment is a static (non-parameter) literal."""
        return not (seg.startswith("<") and seg.endswith(">"))

    def add(self, path, handler):
        segments = self._segments(path)
        # Check if this route has any parameter segments
        has_param = any(not self._is_static_segment(seg) for seg in segments)

        # Store the parsed segments and handler with the appropriate list
        def match(requested_segments):
            """Try to match requested segments against this route's segments."""
            if len(segments) != len(requested_segments):
                return None  # Segment count must match exactly

            params = {}
            for route_seg, req_seg in zip(segments, requested_segments):
                if self._is_static_segment(route_seg):
                    # Static segment: must match exactly
                    if route_seg != req_seg:
                        return None
                else:
                    # Parameter segment: capture the value
                    # An empty segment cannot satisfy a parameter
                    param_name = route_seg[1:-1]  # Extract name from <name>
                    params[param_name] = req_seg
            return params

        if has_param:
            self._dynamic_routes.append((segments, match, handler))
        else:
            self._static_routes.append((segments, match, path, handler))

    def resolve(self, path):
        # First check static routes (they win over dynamic)
        requested_segments = self._segments(path)

        for segments, match, raw_path, handler in self._static_routes:
            params = match(requested_segments)
            if params is not None:
                return handler, {}

        # Then check dynamic routes
        for segments, match, handler in self._dynamic_routes:
            params = match(requested_segments)
            if params is not None:
                return handler, params

        return None, {}
